function reportRows(){if(reportMode=='rentabilidad')return reportVehicles().map(function(v){var inc=sum(reportIncomes().filter(function(i){return i.plate==v.plate}),'value'),exp=sum(reportExpenses().filter(function(e){return e.plate==v.plate}),'value'),deb=sum(reportDebts().filter(function(d){return d.plate==v.plate}),'value'),paid=sum(reportPays().filter(function(p){var d=state.debts.find(function(x){return x.id==p.debt})||{};return d.plate==v.plate}),'value'),sav=sum(reportSavings().filter(function(x){return x.plate==v.plate}),'value'),savRet=sum(reportSavingReturns().filter(function(x){return ((drv(x.driver)||{}).plate==v.plate)||((drvPlate(v.plate)||{}).id==x.driver)}),'value');return{id:v.plate,placa:v.plate,conductor:(drv(v.driver)||{}).name||'Sin asignar',ingresos:money.format(inc),gastos:money.format(exp),deudas:money.format(deb),abonado:money.format(paid),tarifaActiva:(activeTariff(iso(),v.plate,v.driver)||{}).value?money.format(activeTariff(iso(),v.plate,v.driver).value):'Sin tarifa',ahorroConductor:money.format(sav),saldoAhorro:money.format(sav-savRet),utilidad:money.format(inc-exp-deb+paid),estado:v.status}});if(reportMode=='historico')return reportHistoricalRows();if(reportMode=='resumen')return reportDailyRows();return[]}
