var vehTab='resumen';function finance(p){var v=veh(p),inc=sum(state.incomes.filter(function(i){return i.plate==p}),'value'),exp=sum(state.expenses.filter(function(e){return e.plate==p}),'value'),deb=state.debts.filter(function(d){return d.plate==p}).reduce(function(s,d){return s+debtTotal(d.id).bal},0),tabs=[['resumen','Resumen'],['timeline','Timeline'],['docs','Documentos'],['datos','Datos']];$('#modal').className='modalRoot open';$('#modal').innerHTML='<div class="modal"><div class="modalHead"><h2>Ficha '+p+'</h2><button class="icon" onclick="closeM()">x</button></div><div class="tabs vehicleTabs">'+tabs.map(function(t){return '<button class="tab '+(vehTab==t[0]?'on':'')+'" onclick="vehTab=\''+t[0]+'\';finance(\''+p+'\')">'+t[1]+'</button>'}).join('')+'</div><div class="modalBody">'+vehiclePanel(p,vehTab,inc,exp,deb,v)+'</div><div class="modalFoot"><button class="btn" onclick="closeM()">Cerrar</button></div></div>'}
function vehiclePanel(p,mode,inc,exp,deb,v){if(mode=='timeline')return '<div class="timeline">'+vehicleEvents(p).map(function(e){return '<div class="event"><time>'+fmt(e.date)+'</time><div><strong>'+e.t+'</strong><p>'+e.d+'</p></div></div>'}).join('')+'</div>';if(mode=='docs')return table('reportes',state.docs.filter(function(d){return d.plate==p}).map(function(d){var s=docStatus(d.expires);return{id:d.id,tipo:d.type,numero:d.number,vencimiento:fmt(d.expires),estado:s[0]}}));if(mode=='datos')return fieldView([['Placa',p],['Marca',v.brand],['Modelo',v.model],['Año',v.year],['Color',v.color||'Sin dato'],['Conductor',((drvPlate(p)||{}).name||'Sin asignar')],['Estado',v.status]]);return '<div class="metric"><span>Vehiculo</span><strong>'+v.brand+' '+v.model+'</strong></div><div class="metric"><span>Conductor</span><strong>'+((drvPlate(p)||{}).name||'Sin asignar')+'</strong></div>'+[['Ingresos históricos',money.format(inc)],['Gastos históricos',money.format(exp)],['Deudas pendientes',money.format(deb)],['Resultado',money.format(inc-exp-deb)]].map(card).join('')}
function fieldView(a){return a.map(function(x){return '<div class="metric"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></div>'}).join('')}
function vehicleEvents(p){var e=[];state.incomes.filter(function(x){return x.plate==p}).forEach(function(x){e.push({date:x.date,t:'Ingreso',d:money.format(x.value)+' por '+x.method+(incomeExpected(x)?' / esperado '+money.format(incomeExpected(x)):' / libre')})});state.expenses.filter(function(x){return x.plate==p}).forEach(function(x){e.push({date:x.date,t:'Gasto',d:x.cat+' - '+money.format(x.value)})});state.debts.filter(function(x){return x.plate==p}).forEach(function(x){e.push({date:x.date,t:'Deuda',d:x.concept+' - saldo '+money.format(debtTotal(x.id).bal)})});state.docs.filter(function(x){return x.plate==p}).forEach(function(x){e.push({date:x.expires,t:'Documento',d:x.type+' vence este día'})});state.pays.forEach(function(a){var d=state.debts.find(function(x){return x.id==a.debt&&x.plate==p});if(d)e.push({date:a.date,t:'Abono',d:money.format(a.value)+' a '+d.concept})});return e.sort(function(a,b){return b.date.localeCompare(a.date)})}
function rateRows(p,d){return linkTariffs(p,d).map(function(t){return{id:t.id,inicio:fmt(t.start),fin:t.end?fmt(t.end):'',valor:money.format(t.value),periodicidad:t.periodicity,estado:tariffStatus(t),observacion:t.notes||''}})}function openLinkRates(p,d){var v=veh(p)||{},driver=d||v.driver||'',drivers=state.drivers.map(function(x){return[x.id,x.name+' ('+x.id+')']});$('#modal').className='modalRoot open';$('#modal').innerHTML='<div class="modal"><div class="modalHead"><h2>Tarifas '+(p||'vinculación')+'</h2><button class="icon" onclick="closeM()">x</button></div><div class="modalBody"><label class="field full"><span>Conductor de la vinculación</span><select id="rateDriver" onchange="openLinkRates(\''+p+'\',this.value)">'+opts(drivers).map(function(x){return'<option value="'+x[0]+'" '+(String(x[0])==String(driver)?'selected':'')+'>'+x[1]+'</option>'}).join('')+'</select></label><div class="metric"><span>Tarifa activa</span><strong>'+((activeTariff(iso(),p,driver)||{}).value?money.format(activeTariff(iso(),p,driver).value):'Sin tarifa')+'</strong></div></div>'+table('reportes',rateRows(p,driver))+'<div class="modalFoot"><button class="ghost" onclick="newTariff(\''+p+'\',document.querySelector(\'#rateDriver\').value)">Nueva tarifa</button><button class="btn" onclick="closeM()">Cerrar</button></div></div>'}function openDriverRates(id){var d=drv(id)||{};openLinkRates(d.plate||((state.vehicles.find(function(v){return v.driver==id})||{}).plate)||'',id)}function newTariff(p,d){if(!p||!d)return toast('Selecciona vehículo y conductor.');modal('Nueva tarifa de vinculación',[field('value','Valor','number','',1),field('periodicity','Periodicidad','select','Diaria',1,['Diaria','Semanal','Quincenal','Mensual','Ocasional']),field('start','Inicio de vigencia','date',iso(),1),field('end','Fin de vigencia','date','',0),field('status','Estado','select','Activa',1,['Activa','Programada','Finalizada']),field('notes','Observaciones','textarea','',0,[],'full')],function(v){var amount=val(v.value);if(amount<=0){toast('La tarifa debe ser mayor que cero.');return false}if(v.end&&v.end<v.start){toast('La fecha final no puede ser anterior al inicio.');return false}var n={id:uid('tar'),plate:p,driver:d,value:amount,periodicity:v.periodicity,start:v.start,end:v.end,status:v.status,notes:v.notes,created:new Date().toISOString()};state.tariffs=state.tariffs||[];state.tariffs.forEach(function(t){if(t.plate==p&&t.driver==d&&tariffStatus(t)=='Activa'&&t.start<n.start&&!t.end){t.end=add(n.start,-1);t.status='Finalizada'}});state.tariffs.push(n);save();var changed=state.tariffs.filter(function(t){return t.plate==p&&t.driver==d&&t.status=='Finalizada'});Promise.all([pushSheetChange('save:tariffs',n)].concat(changed.map(function(t){return pushSheetChange('save:tariffs',t)}))).then(function(){toast('Tarifa guardada.');openLinkRates(p,d)}).catch(function(){toast('Tarifa local; pendiente sincronizar.');openLinkRates(p,d)});return true})}function openDriverSavings(id){var d=drv(id)||{},dep=driverSavings(id),ret=driverSavingReturns(id),bal=driverSavingBalance(id),mov=dep.map(function(x){return{id:x.id,fecha:fmt(x.date),tipo:'Ahorro',placa:x.plate,valor:money.format(x.value),observacion:x.notes||''}}).concat(ret.map(function(x){return{id:x.id,fecha:fmt(x.date),tipo:'Devolución',placa:'',valor:money.format(-val(x.value)),observacion:x.notes||''}})).sort(function(a,b){return b.fecha.localeCompare(a.fecha)});$('#modal').className='modalRoot open';$('#modal').innerHTML='<div class="modal"><div class="modalHead"><h2>Ahorro '+(d.name||id)+'</h2><button class="icon" onclick="closeM()">x</button></div><div class="modalBody"><div class="metric"><span>Saldo disponible</span><strong>'+money.format(bal)+'</strong></div><div class="metric"><span>Total ahorrado</span><strong>'+money.format(sum(dep,'value'))+'</strong></div><div class="metric"><span>Devuelto</span><strong>'+money.format(sum(ret,'value'))+'</strong></div></div>'+table('reportes',mov)+'<div class="modalFoot"><button class="ghost" onclick="returnSaving(\''+id+'\')">Registrar devolución</button><button class="btn" onclick="closeM()">Cerrar</button></div></div>'}function returnSaving(id){var bal=driverSavingBalance(id);if(bal<=0)return toast('El conductor no tiene ahorro disponible.');modal('Registrar devolución de ahorro',[field('date','Fecha','date',iso(),1),field('value','Valor a devolver, máximo '+money.format(bal),'number','',1),field('notes','Observación','textarea','',0,[],'full')],function(v){var a=val(v.value);if(a<=0||a>bal){toast('La devolución no puede superar el saldo disponible.');return false}var n={id:uid('dev'),date:v.date,driver:id,value:a,notes:v.notes,user:state.settings.user,created:new Date().toISOString()};state.savingReturns=state.savingReturns||[];state.savingReturns.push(n);save();pushSheetChange('save:savingReturns',n).then(function(ok){toast(ok?'Devolución guardada en libro.':'Devolución guardada localmente.');openDriverSavings(id)}).catch(function(){toast('Devolución local; pendiente sincronizar.');openDriverSavings(id)});return true})}function closeM(){$('#modal').className='modalRoot';$('#modal').innerHTML=''}

function apiUrl(action){var sep=API_ENDPOINT.indexOf('?')>-1?'&':'?';return API_ENDPOINT+sep+'action='+encodeURIComponent(action)+'&cache='+Date.now()}
async function loadFromCsv(){var db={settings:{},vehicles:[],drivers:[],incomes:[],expenses:[],debts:[],pays:[],docs:[],tariffs:[]};for(var i=0;i<SHEET_TABS.length;i++){var tab=SHEET_TABS[i],res=await fetch(sheetUrl(tab));if(!res.ok)throw new Error(tab+' '+res.status);var data=rowsToObjects(csvRows(await res.text()));if(tab=='settings')data.forEach(function(r){if(r.key)db.settings[r.key]=r.value});else db[tab]=data}return db}
async function loadSheetDB(){toast('Sincronizando libro...');var db;if(API_ENDPOINT){var res=await fetch(apiUrl('read'));if(!res.ok)throw new Error('api '+res.status);var json=await res.json();if(!json.ok)throw new Error(json.error||'api');db=json.data||{}}else{db=await loadFromCsv()}state=cleanState(db);state.settings.apiUrl=API_ENDPOINT;state.source={spreadsheetId:SHEET_ID,syncedAt:new Date().toISOString()};save();render();toast('Libro sincronizado.')}
async function pushSheetChange(kind,row){var endpoint=API_ENDPOINT||WRITE_ENDPOINT;if(!endpoint)return false;await fetch(endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({kind:kind,row:row})});return true}
async function syncNow(){try{if(!API_ENDPOINT)toast('Pega la URL de Apps Script en Configuración.');await loadSheetDB()}catch(e){toast(API_ENDPOINT?'No se pudo sincronizar el backend.':'No se pudo leer el libro. Falta conectar Apps Script.');console.error(e)}}
function config(){$('#view').innerHTML='<section class="panel"><div class="head"><h2>Parámetros generales</h2></div><div class="modalBody"><label class="field"><span>Días de alerta documental</span><input id="alertDays" type="number" value="'+state.settings.alertDays+'"></label><label class="field"><span>Usuario por defecto</span><input id="user" value="'+state.settings.user+'"></label><label class="field full"><span>Backend de Google Sheets</span><input value="Conectado al libro REENTRY APP" disabled></label></div></section>'}
function saveConfig(){state.settings.alertDays=val($('#alertDays').value)||30;state.settings.user=$('#user').value||'Admin local';API_ENDPOINT=DEFAULT_API_ENDPOINT;WRITE_ENDPOINT=DEFAULT_API_ENDPOINT;state.settings.apiUrl=DEFAULT_API_ENDPOINT;localStorage.setItem(API_KEY,DEFAULT_API_ENDPOINT);save();pushSheetChange('settings',state.settings).then(function(ok){toast(ok?'Configuración global guardada.':'Configuración guardada localmente.');render()}).catch(function(){toast('Configuración local; pendiente sincronizar.')})}
render();syncNow();


